import * as THREE from 'three';
import {buildInterior} from './floor-interior.js';
import {createTransition,easeInOut,phase} from './transitions.js';

// Relative demo coordinates, explicitly separate from the outdoor inventory.
export function floorDevices(b,floor){
 const step=(b.h-b.base)/b.floors;
 const x=b.kind==='crescent'?-65:b.kind==='courtyard'?45:b.x;
 const z=b.kind==='crescent'?5:b.z;
 const dx=b.kind==='crescent'?5:b.w*.2, dz=b.kind==='crescent'?17:b.d*.18;
 return [['camera',-dx,-dz],['camera',dx,dz],['door',0,0],['fire',dx,-dz]].map(([type,ox,oz],i)=>({id:`${b.id.toUpperCase()}-${floor}F-${type.toUpperCase()}-${i+1}`,building:b.id,floor,type,x:x+ox,y:b.base+(floor-1)*step+1.2,z:z+oz}));
}
export function createFloorBrowser({scene,camera,controls,meshes,host,onExit,onFocus,onDevice,motionEnabled=()=>true}){
 let building=null,chosen=null,saved=[],floors=[],points=[],floorLabels=[],counts=[],interiors=[],interiorLabels=[],interiorVisible=true,transition=null,viewBlend=1;
 const root=new THREE.Group();root.name='楼栋分层';scene.add(root);
 const overlay=document.createElement('div');overlay.className='floor-overlays';host.appendChild(overlay);
 const panel=document.createElement('section');panel.className='floor-panel';panel.hidden=true;host.appendChild(panel);
 const cue=document.createElement('div');cue.className='floor-transition-cue';cue.hidden=true;host.appendChild(cue);
 const symbol={camera:'◉',door:'▥',fire:'♧'},names={camera:'摄像头',door:'门禁',fire:'消防'};
 function exit(){transition?.cancel();transition=null;host.classList.remove('floor-transitioning');cue.hidden=true;if(!building)return;camera.clearViewOffset();saved.forEach(([o,v])=>o.visible=v);saved=[];counts.forEach(([el,value])=>el.textContent=value);counts=[];chosen=null;for(const g of floors)g.traverse(o=>{if(o.isMesh){if(o.userData.interiorOwned){o.geometry.dispose();o.material.map?.dispose();}o.material.dispose();}});root.clear();overlay.replaceChildren();panel.hidden=true;building=null;floors=[];points=[];floorLabels=[];interiors=[];interiorLabels=[];host.classList.remove('floor-active');}
 function focus(){onFocus();const box=new THREE.Box3();root.updateMatrixWorld(true);floors.filter(g=>g.visible).forEach(g=>box.expandByObject(g));const size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());const span=Math.max(size.x/Math.max(camera.aspect,.5),size.z,size.y,30);const dist=span/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*1.45;controls.target.copy(center);camera.position.copy(center).add((chosen===null?new THREE.Vector3(-.7,.95,1):new THREE.Vector3(-.25,1.5,.65)).normalize().multiplyScalar(dist));controls.update();}
 function show(floor){if(!building)return;transition?.cancel();transition=null;
 const fromBlend=viewBlend;const fromCamera=camera.position.clone(),fromTarget=controls.target.clone();const starts=floors.map(g=>({position:g.position.clone(),visible:g.visible}));chosen=floor;document.querySelectorAll('[data-layer]').forEach(el=>{const count=el.querySelector('b');if(count)count.textContent=String(({camera:2,door:1,fire:1,patrol:0}[el.dataset.layer]??0)*(floor===null?building.floors:1));});floors.forEach((g,i)=>{g.visible=floor===null||floor===i+1;g.position.y=floor===null?i*9:-building.base-i*(building.h-building.base)/building.floors;g.position.x=0;});interiors.forEach(({group})=>group.visible=interiorVisible);floors.forEach(g=>g.children.filter(m=>m.userData.envelope).forEach(m=>m.visible=!(chosen!==null&&interiorVisible)));panel.querySelector('.floor-current').textContent=floor===null?'各层展开 · 点击楼层查看':`${floor}F · 单层隔离 · 4 个演示点位`;panel.querySelectorAll('[data-floor]').forEach(b=>b.classList.toggle('active',Number(b.dataset.floor)===floor));panel.querySelector('[data-action="explode"]').classList.toggle('active',floor===null);focus();
 const toCamera=camera.position.clone(),toTarget=controls.target.clone();const ends=floors.map(g=>({position:g.position.clone(),visible:g.visible}));
 if(!motionEnabled()){viewBlend=1;floors.forEach(g=>g.traverse(m=>{const state=m.userData.motionMaterial;if(state)Object.assign(m.material,state);}));host.classList.remove('floor-transitioning');cue.hidden=true;return;}
 camera.position.copy(fromCamera);controls.target.copy(fromTarget);controls.update();
 const materialStates=[];floors.forEach((g,i)=>g.traverse(m=>{if(m.isMesh){const original=m.userData.motionMaterial||(m.userData.motionMaterial={opacity:m.material.opacity,transparent:m.material.transparent,depthWrite:m.material.depthWrite});materialStates.push({m,index:i,...original,interior:!!m.userData.interiorOwned});m.material.transparent=true;m.material.depthWrite=false;}}));
 host.classList.add('floor-transitioning');cue.hidden=false;cue.innerHTML=`<span class="transition-orbit"></span><div><b>${building.name}${floor===null?' · 楼层展开':` · ${floor}F`}</b><small>${floor===null?'正在进入楼栋':'正在进入楼层平面'}</small></div>`;
 transition=createTransition({duration:floor===null?1400:1150,onUpdate:t=>{
  viewBlend=fromBlend+(1-fromBlend)*phase(t,0,.8);const cameraT=easeInOut(t);camera.position.lerpVectors(fromCamera,toCamera,cameraT);camera.position.y+=Math.sin(t*Math.PI)*Math.min(18,fromCamera.distanceTo(toCamera)*.045);controls.target.lerpVectors(fromTarget,toTarget,cameraT);
  floors.forEach((g,i)=>{const end=ends[i];g.visible=starts[i].visible||end.visible;const lag=floor===null?i/floors.length*.22:0;const progress=phase(t,lag,.95);g.position.lerpVectors(starts[i].position,end.position,progress);if(!end.visible){g.position.x=starts[i].position.x+(i+1<floor?-18:18)*phase(t,0,.5);g.position.y=starts[i].position.y+(i+1<floor?-16:20)*phase(t,0,.5);if(t>.55)g.visible=false;}});
  for(const state of materialStates){let opacity=ends[state.index].visible?1:1-phase(t,0,.5);if(!starts[state.index].visible&&ends[state.index].visible)opacity*=phase(t,.1,.7);if(state.interior&&floor!==null)opacity*=phase(t,.35,.9);state.m.material.opacity=state.opacity*opacity;}
  host.style.setProperty('--transition-progress',String(t));controls.update();
 },onComplete:()=>{viewBlend=1;floors.forEach((g,i)=>{g.position.copy(ends[i].position);g.visible=ends[i].visible;});for(const state of materialStates){state.m.material.opacity=state.opacity;state.m.material.transparent=state.transparent;state.m.material.depthWrite=state.depthWrite;}host.classList.remove('floor-transitioning');cue.hidden=true;transition=null;}});
 transition.step(performance.now());
 }
 function enter(b){exit();viewBlend=0;counts=[...document.querySelectorAll('[data-layer] b')].map(el=>[el,el.textContent]);building=b;host.classList.add('floor-active');saved=scene.children.filter(o=>o!==root&&!o.isLight).map(o=>[o,o.visible]);saved.forEach(([o])=>o.visible=false);
  for(let f=1;f<=b.floors;f++){const g=new THREE.Group();root.add(g);floors.push(g);const sources=meshes.filter(m=>m.userData.building.id===b.id&&m.userData.floor===f);for(let j=0;j<sources.length;j++){const source=sources[j],m=new THREE.Mesh(source.geometry,source.material.clone());m.position.copy(source.position);m.userData.floor=f;m.userData.envelope=j!==0;m.material.wireframe=false;m.material.transparent=j!==0;m.material.opacity=j===0?1:.12;m.material.depthWrite=j===0;g.add(m);}
   const interior=buildInterior(b,f);g.add(interior.group);interiors.push(interior);
   for(const marker of interior.markers){const el=document.createElement('span');el.className=`interior-label ${marker.kind}`;el.textContent=marker.label;overlay.appendChild(el);interiorLabels.push({el,group:g,position:marker.position,interior:true});}
   const label=document.createElement('button');label.className='floor-label';label.textContent=`${f}F`;label.onclick=()=>show(f);overlay.appendChild(label);floorLabels.push({el:label,group:g,floor:f,position:new THREE.Vector3(b.kind==='crescent'?-82:b.x-b.w/2,b.base+(f-1)*(b.h-b.base)/b.floors+1,b.z)});
   for(const d of floorDevices(b,f)){const el=document.createElement('button');el.className=`map-point ${d.type}`;el.textContent=symbol[d.type];el.title=`${f}F ${names[d.type]} · 演示`;el.setAttribute('aria-label',d.id);let down=null;el.onpointerdown=e=>{down=[e.clientX,e.clientY];el.setPointerCapture(e.pointerId);};el.onpointercancel=()=>down=null;el.onpointerup=e=>{e.preventDefault();e.stopPropagation();if(down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<6)onDevice(d,names[d.type]);down=null;};el.onclick=e=>{if(e.detail===0)onDevice(d,names[d.type]);};overlay.appendChild(el);points.push({el,group:g,position:new THREE.Vector3(d.x,d.y,d.z),d});}
  }
  panel.innerHTML=`<div class="floor-panel-head"><b>${b.name} · 楼层浏览</b><button data-action="exit">返回院区 ×</button></div><p class="floor-current"></p><div class="floor-actions"><button data-action="explode">展开全部楼层</button><button data-action="top">俯视本层</button></div><div class="floor-buttons">${Array.from({length:b.floors},(_,i)=>`<button data-floor="${i+1}">${i+1}F</button>`).reverse().join('')}</div><button class="interior-toggle" data-action="interior" aria-pressed="true">✓ 房间 / 楼梯 / 电梯</button><div class="interior-legend"><span>▧ 房间</span><span>▰ 走廊</span><span>▤ 楼梯</span><span>↕ 电梯</span></div><p class="floor-note">室内布局为演示，不代表真实科室或疏散路线。楼层编号为模型内演示编号。点位、层高按示意配置，未接入真实室内平面。</p>`;
  panel.querySelector('[data-action="exit"]').onclick=()=>{exit();onExit();};panel.querySelector('[data-action="explode"]').onclick=()=>show(null);panel.querySelector('[data-action="top"]').onclick=()=>{finish(true);onFocus();const from=camera.position.clone();const box=new THREE.Box3();floors.filter(g=>g.visible).forEach(g=>box.expandByObject(g));const size=box.getSize(new THREE.Vector3());const distance=Math.max(size.x/camera.aspect,size.z,30)/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*1.7;const to=controls.target.clone().add(new THREE.Vector3(0,distance,.001));if(!motionEnabled()){camera.position.copy(to);controls.update();return;}transition=createTransition({duration:850,onUpdate:t=>{camera.position.lerpVectors(from,to,easeInOut(t));controls.update();},onComplete:()=>transition=null});};panel.querySelectorAll('[data-floor]').forEach(el=>el.onclick=()=>show(Number(el.dataset.floor)));panel.querySelector('[data-action="interior"]').onclick=()=>{finish(true);interiorVisible=!interiorVisible;interiors.forEach(({group})=>group.visible=interiorVisible);floors.forEach(g=>g.children.filter(m=>m.userData.envelope).forEach(m=>m.visible=!(chosen!==null&&interiorVisible)));const btn=panel.querySelector('[data-action="interior"]');btn.setAttribute('aria-pressed',String(interiorVisible));btn.textContent=`${interiorVisible?'✓':'○'} 房间 / 楼梯 / 电梯`;};interiorVisible=true;panel.hidden=false;show(null);
 }
 function finish(preserveCamera=false){if(!transition)return;const position=camera.position.clone(),target=controls.target.clone();transition.finish();if(preserveCamera){camera.position.copy(position);controls.target.copy(target);controls.update();}}
 const projected=new THREE.Vector3();
 function update(){if(!building)return;if(transition){if(!motionEnabled())finish();else transition.step(performance.now());}const w=host.clientWidth,h=host.clientHeight;const compact=w<=720,ox=compact?0:(panel.offsetWidth+18)/2*viewBlend,oy=compact?(panel.offsetHeight+56)/2*viewBlend:0;const view=camera.view;if(!view?.enabled||view.fullWidth!==w||view.fullHeight!==h||view.offsetX!==ox||view.offsetY!==oy)camera.setViewOffset(w,h,ox,oy,w,h);root.updateMatrixWorld(true);for(const p of [...floorLabels,...points,...interiorLabels]){const layer=p.d?document.querySelector(`[data-layer="${p.d.type}"]`):null;let hidden=!p.group.visible||(transition?.active&&p.d)||(transition?.active&&p.interior)||(p.interior&&(!interiorVisible||chosen===null))||(layer&&!layer.classList.contains('active'));if(!hidden){projected.copy(p.position).add(p.group.position).project(camera);hidden=projected.z>1||projected.z<-1;const left=`${(projected.x*.5+.5)*host.clientWidth}px`,top=`${(-projected.y*.5+.5)*host.clientHeight}px`;if(p.el.style.left!==left)p.el.style.left=left;if(p.el.style.top!==top)p.el.style.top=top;}if(p.el.hidden!==!!hidden)p.el.hidden=!!hidden;}}

 function pick(raycaster){if(!building)return false;if(transition?.active)return true;const candidates=floors.filter(g=>g.visible).flatMap(g=>g.children);const hit=raycaster.intersectObjects(candidates,false)[0];if(hit)show(hit.object.userData.floor);return true;}
 return {enter,exit,update,pick,finish,get active(){return !!building;},get selectedFloor(){return chosen;}};
}
